// Кейс: .qa/tests/summary/SUM-005.md · план: .qa/e2e-app/specs/app.md (1.5)
// Итог ниטור через «היסטוריה» → верхний сеанс: длительность, число сбоев/тревог (= строке истории), дети RTL, «מה קרה».
// Мониторинг НЕ запускается — смотрим уже существующий сеанс. Только просмотр.
import { by, assert } from '../../lib/appium.mjs';
import { onHome, openTab } from '../../lib/banci.mjs';

export const name = 'היסטוריה → последний ניטור: длительность, «X תקלות בניטור»/«התרעה אחת», «…היו בבריכה» RTL, «מה קרה» #25e8f258 @iphone @app @prod-safe';

/** Строка сеанса в истории: «N דק׳ ניטור» / «… שעה … ניטור». */
const ROW = '(name CONTAINS "ניטור" OR label CONTAINS "ניטור") AND (name CONTAINS "דק" OR label CONTAINS "דק" OR name CONTAINS "שע" OR label CONTAINS "שע") AND NOT (name CONTAINS "ניטורים" OR label CONTAINS "ניטורים")';
const DURATION = 'name MATCHES ".*[0-9]+ ?(דק|שע).*" OR label MATCHES ".*[0-9]+ ?(דק|שע).*"';

async function topmost(els) {
  const rects = await Promise.all(els.map((e) => e.rect()));
  let best = 0;
  rects.forEach((r, i) => { if (r.y < rects[best].y) best = i; });
  return { el: els[best], rect: rects[best] };
}

/** Число событий из текста строки истории: { kind: 'alert'|'failure', n } или null. */
function countFrom(text) {
  const t = String(text);
  if (/התרעה אחת/.test(t)) return { kind: 'alert', n: 1 };
  if (/כשל אחד|תקלה אחת/.test(t)) return { kind: 'failure', n: 1 };
  const a = t.match(/(\d+)\s*התרעות/);
  if (a) return { kind: 'alert', n: +a[1] };
  const f = t.match(/(\d+)\s*(כשלים|תקלות)/);
  if (f) return { kind: 'failure', n: +f[1] };
  return null;
}

export default async function (app) {
  const { width: W } = await app.windowRect();

  // 1. «היסטוריה» → верхняя запись сеанса.
  await onHome(app);
  await openTab(app, 'היסטוריה');
  await app.waitFor(ROW, { timeout: 20000, what: 'ПРЕДУСЛОВИЕ: в «היסטוריה» есть хотя бы один сеанс («N דק׳ ניטור»)' });
  const { el: row } = await topmost(await app.findAll(ROW));
  const rowText = `${await row.attr('label') ?? ''} ${await row.attr('name') ?? ''}`;
  const expected = countFrom(rowText);
  await row.click();

  // 2. Детали: длительность и «מה קרה».
  await app.waitFor(by.exact('מה קרה'), { timeout: 15000, what: 'блок «מה קרה» в деталях сеанса' });
  assert(await app.exists(DURATION), 'в деталях есть длительность «N דק׳» (AC2)');

  // 3. Число сбоев/тревог совпадает со строкой истории (AC4, AC5).
  if (expected) {
    const word = expected.kind === 'alert' ? 'התרעה' : 'תקלה';
    const want = expected.n === 1
      ? by.contains(`${word} אחת`)
      : by.contains(`${expected.n} ${expected.kind === 'alert' ? 'התרעות' : 'תקלות'}`);
    assert(await app.exists(want), `в деталях число событий как в строке истории («${rowText.trim()}» → ${expected.n} ${expected.kind === 'alert' ? 'התרעות' : 'תקלות בניטור'})`);
  }

  // 4. Дети: «… היו בבריכה» / «… היה/הייתה בבריכה», выровнено вправо (RTL).
  const kids = await app.waitFor(by.contains('בבריכה', 'StaticText'), { what: 'строка детей «… היו בבריכה» (AC3)' });
  const kr = await kids.rect();
  if (kr.width < W * 0.9) {
    assert(kr.x + kr.width > W * 0.65, `строка детей прижата вправо (x=${Math.round(kr.x)}, w=${Math.round(kr.width)}, экран ${W})`);
  }
  const kidsText = String(await kids.attr('label') ?? await kids.attr('name'));
  assert(!/ ו[A-Za-z]/.test(kidsText), `перед латинским именем «ו-» с дефисом («${kidsText}»)`);

  // 5. «מה קרה»: начало и конец сеанса.
  await app.scrollTo(by.contains('התחלת ניטור'), { max: 3, what: '«התחלת ניטור» в «מה קרה»' });
  await app.scrollTo('(name CONTAINS "הניטור הסתיים" OR label CONTAINS "הניטור הסתיים" OR name CONTAINS "הניטור הופסק" OR label CONTAINS "הניטור הופסק")', { max: 6, what: '«הניטור הסתיים» (или «הניטור הופסק…») в конце «מה קרה»' });
}
